// Noto Sans Arabic, embedded for the PDF exporter.
//
// Why this file exists: jsPDF's built-in faces are the PDF standard-14 - Helvetica,
// Courier, Times - and every one of them is WinAnsi-encoded, which has no Arabic in it.
// jsPDF *does* shape Arabic correctly on its own (it converts the letters to their
// contextual presentation forms and reverses the run), so the bytes that reach the file
// are right; there is simply no font in the document that can draw them. The result is
// that an Arabic customer name prints on the client's ticket as Latin-1 rubbish -
// see BLINDSPOTS B-5.2, which predicted exactly this.
//
// The face is the family's own Arabic and Latin subsets merged back together and pinned
// to Regular: jsPDF has no variable-font machinery, and a mixed name must not lose
// whichever half the font cannot draw.
// Presentation forms U+FB50-FDFF and U+FE70-FEFC are kept deliberately - those are the
// codepoints jsPDF actually emits, and a font that only carried the base U+0600 block
// would embed cleanly and still draw nothing.
//
// Loaded from disk beside jsPDF, never from a CDN, and precached in sw.js: the whole
// point is that a technician at a wellhead with no signal can still produce the sheets.
// Once embedded the PDF is self-contained, so it also renders on a machine that has
// never had an Arabic font installed.
(function (root) {
  var TTF = '';
  root.MK_ARABIC_FONT = {
    file: 'NotoSansArabic-Regular.ttf',
    name: 'NotoSansArabic',
    b64: TTF,
    // Registers the face on one jsPDF document. Called per document rather than through
    // the global plugin hook so nothing is added to a PDF that has no Arabic in it.
    register: function (doc) {
      doc.addFileToVFS('NotoSansArabic-Regular.ttf', TTF);
      doc.addFont('NotoSansArabic-Regular.ttf', 'NotoSansArabic', 'normal');
      return 'NotoSansArabic';
    },
  };
})(typeof window !== 'undefined' ? window : this);
